SELECT EXISTS (
    SELECT 1
    FROM tb_emp
    WHERE emp_id = #{userId}
)

SELECT EXISTS (
    SELECT 1
    FROM tb_emp
    WHERE hosp_div_id = #{hospitalId}
      AND role_cd = 'USER'
      AND auth_st = 'APPROVED'
      AND phone_no = #{phoneNumber}
)

SELECT EXISTS (
    SELECT 1
    FROM tb_ward
    WHERE hosp_div_id = #{hospitalId}
      AND ward_id = #{wardId}
)
